    "paragraphs": [
      "2024 saw some early signs of life from the Chinese AI labs mainly in the form of Qwen 2.5 and early DeepSeek. They were neat models but didn't feel world-beating.",
      "This changed dramatically in 2025. My ai-in-china tag has 67 posts from 2025 alone, and I missed a bunch of key releases towards the end of the year (GLM-4.7 and MiniMax-M2.1 in particular.)",
      "Here's the Artificial Analysis ranking for open weight models as-of 30th December 2025:",
      "GLM-4.7, Kimi K2 Thinking, MiMo-V2-Flash, DeepSeek V3.2, MiniMax-M2.1 are all Chinese open weight models. The highest non-Chinese model in that chart is OpenAI's gpt-oss-120B (high), which comes in sixth place.",
      "The Chinese model revolution really kicked off on Christmas day 2024 with the release of DeepSeek 3, supposedly trained for around $5.5m. DeepSeek followed that on 20th January with DeepSeek R1 which promptly triggered a major AI/semiconductor selloff: NVIDIA lost ~$593bn in market cap as investors panicked that AI maybe wasn't an American monopoly after all.",
      "The panic didn't last—NVIDIA quickly recovered and today are up significantly from their pre-DeepSeek R1 levels. It was still a remarkable moment. Who knew an open weight model release could have that kind of impact?",
      "DeepSeek were quickly joined by an impressive roster of Chinese AI labs. I've been paying attention to these ones in particular:",
      "• DeepSeek • Alibaba Qwen (Qwen3) • Moonshot AI (Kimi K2) • Z.ai (GLM-4.5/4.6/4.7) • MiniMax (M2) • MetaStone AI (XBai o4)",
      "Most of these models aren't just open weight, they are fully open source under OSI-approved licenses: Qwen use Apache 2.0 for most of their models, DeepSeek and Z.ai use MIT.",
      "Sadly none of the Chinese labs have released their full training data or the code they used to train their models, but they have been putting out detailed research papers that have helped push forward the state of the art, especially when it comes to efficient training and inference.",
      "2025 is where I (and I think the rest of the industry also) first started to internalize the \"shape\" of LLM intelligence in a more intuitive sense. We're not \"evolving/growing animals\", we are \"summoning ghosts\". Everything about the LLM stack is different (neural architecture, training data, training algorithms, and especially optimization pressure) so it should be no surprise that we are getting very different entities in the intelligence space, which are inappropriate to think about through an animal lens. Supervision bitswise, human neural nets are optimized for survival of a tribe in the jungle but LLM neural nets are optimized for imitating humanity's text, collecting rewards in math puzzles, and getting that upvote from a human on the LM Arena. As verifiable domains allow for RLVR, LLMs \"spike\" in capability in the vicinity of these domains and overall display amusingly jagged performance characteristics - they are at the same time a genius polymath and a confused and cognitively challenged grade schooler, seconds away from getting tricked by a jailbreak to exfiltrate your data.",
      "Related to all this is my general apathy and loss of trust in benchmarks in 2025. The core issue is that benchmarks are almost by construction verifiable environments and are therefore immediately susceptible to RLVR and weaker forms of it via synthetic data generation. In the typical benchmaxxing process, teams in LLM labs inevitably construct environments adjacent to little pockets of the embedding space occupied by benchmarks and grow jaggies to cover them. Training on the test set is a new art form.",
      "What does it look like to crush all the benchmarks but still not get AGI?",
      "I have written a lot more on the topic of this section here: • Animals vs. Ghosts • Verifiability • The Space of Minds"
    ],
