      "部分特工携带步枪和防 暴盾牌，走上陶家的前门台阶，敲了几次门并等待约一分钟后，用撞门锤破门而入。“”“”看到他被这样带走，哈伯曼说，那种沮丧感扑面而来。",
      "5 据陶家人在众筹页面上的描述，特工进入屋内后，用枪指着陶先生的家人并给他戴上手铐，而他 岁的孙子当时就坐在沙发上目 睹了这一切。",
      "据哈伯曼所述及突袭视频显示，几分钟后，在大雪纷飞中，陶仅披着一条红毯子就被带走了。执法人员将他押入一 SUV 辆黑色，车辆随即疾驰而去。陶先生被带着兜转近一个小时，期间一直接受盘问。",
