      "不可否认，这类事物起初往往足够热忱且纯粹，但很快——“”正如预料的那样 就会被一群捞快钱的骗子接管。随着各种项目相继 卷款跑路，整个行业在重重骗局的重压下最终崩盘。OpenClaw AI AI 相比之下，运动显然更具正当性，更像是这场宏大 革命中一个有趣、且在某种程度上顺理成章的分支。人们对 感“Big AI”——“”OpenAI Anthropic 到兴奋，但又警惕大科技公司（以及所谓的 那些估值动辄数千亿、披着 初创公司 外衣的、和 xAI OpenClaw 们）掌控局面乃至主宰未来。恰好成了缓解这种焦虑的一剂良药，甚至在经历了几次滑稽的品牌名字变动后，它依 Facebook MySpace OpenSocial 然顽强地生存了下来。",
      "不过，这更让我联想到早期社交网络崛起的年代。超越 之际，随之应运而生，试图对抗前者的不可阻挡之势。OpenSocial“”正如当年的 一样，我怀疑这场运动能否长久，或者说除了贡献一些猎奇的趣闻外，能否真正 成气候。这种观点可“能会激怒一些人，因为此类运动往往带有近乎宗教般的狂热。而且，我认识并欣赏很多参与其中的人。从理论上讲，人们崇尚 开”“”——放，这个词天然听起来就像是 正确答案 权力归于人民而非公司，诸如此类。但在现实中，我们一次又一次看到开放系统 AI“”被封闭、完善的产品击败。不是每次，但常常如此。",
      "尤其当竞争的筹码和规模上升到 这种量级时，社区构建的 开放 方案或 许起步强劲，但最终往往会陷入想法相互抵牾、进展迟滞的困境。OpenClaw OpenClaw 此外，我也预见到那些巨头们会对 广受欢迎的功能给出自己的应对之策。运动固然有趣，但抛开头条不谈，Mac mini OpenClaw bot——大众绝不会为了跑一个本地实例而扎堆去买。更何况，大多数人根本不该自己搭 这本身就是各种安全 OpenClaw 灾难的配方。再加上人们天然倾向于选择好用、顺手的产品，这场博弈的终局已然清晰。而那个终局，并不是一个供 bot 社交的网络。",
      "AI——Google Glass——AI 唯一的变量，或许还是前文提到的那种对 的普遍迟疑。与过去任何技术相比 也许除了 人们对 似乎有 AI 一种天然的抗拒。尤其在美国市场，这里虽处于技术前沿，但你几乎读到的每一篇 报道，背后都是对失业的恐惧。但我依然不 OpenClaw Claude——Anthropic 认为这群人会把 视为出路。某种意义上，我们或许正看到用户转向 这和政府与 之间那场风波不无 Anthropic“”AI 关系。受此影响，人们开始将 视为更 讲伦理 的 选择，这也许能帮他们迈过最初那道怀疑的门槛。",
      "AI“AI”随着 革命的深入，我一直在思考：我们终究会不会与某个 真命天 安定下来？也许未来会是工作用一套、生活用另一套；但考虑到几大巨头都在拼命打造全能生态，我想最终选定其一的可能性更大。不过，如果龙虾大会的参与者们被迫进入这种关系，——也许他们会奋起反抗，转而要求把自己变成一种自己挑选的动物 就像某部荒诞电影里的情节。"
