      "当天总理纳伦德拉 莫迪将出席开幕式，但媒体的入场时间始终没有明确通知。6 我们最终得知可以在当地时间早上 点入场。可赶到现场后，安保人员直到大批媒体在门口聚集后才放行。",
      "进入会场后，安保给 出的指引也前后矛盾。多位参会代表向我表达了对峰会组织工作的不满。· 活动本身还伴随着其他争议。",
      "曾出现在爱泼斯坦相关文件中的比尔 盖茨，原定发表主旨演讲，但他是否会现身一度成谜。盖茨 基金会本周早些时候还确认他会出席，周四却突然宣布这位亿万富豪已退出活动。",
