      "毕竟，培养 人才是当务之急。·“”印度信息技术部长阿什维尼 瓦什瑙周二已就峰会首日出现的 问题 公开道歉。",
      "AI“”OpenAI 峰会期间，还有一段两位 巨头的 牵手名场面 在网络疯传。莫迪邀请参会嘉宾上台，示意大家手拉手。",
      "但 首席执行 · Anthropic · 官萨姆 奥尔特曼与 首席执行官达里奥 阿莫迪并未照做，这一幕立刻在社交媒体上引发热议。",
