    "exerciseText": "1.\n根据英文释义写出文中出现的对应单词\n_________: to develop or make sth. develop a new form or structure, because of a genetic change\n_________: to make your skin or a part of your body painful\n2.\n一词多义\nWhich of the following underlined words is closest in meaning to the one in the sentence \"This meningitis\noutbreak is deeply unusual and defies easy explanation.\"? ____\nA. It's a devastating and barbaric act that defies all comprehension.\nB. Hundreds of people today defied the ban on political gatherings.\nC. They defied an evacuation order and stayed in town during the hurricane.\nD. The young player defied all expectations and played far better than anyone had imagined.\n3.\n根据给定中文回译英文\n那么，一种需要密切且持续接触才能传播、传播速度远慢于麻疹、新冠或流感的感染，为什么会\n引发如此迅猛的疫情？答案至关重要，但目前并不清晰。到目前为止，这似乎是在看似普通的环\n境中发生的一次特殊疫情。\n_____________________________________________________________________________________\n_________________________________________________________________",
